/* ==UserStyle==
@name MercadoLibre Argentina - Gris Oscuro (Optimizado)
@namespace mercadolibre
@version 1.2.0
@description Convierte el fondo blanco en gris sin tapar imágenes ni productos.
@match *://www.mercadolibre.com.ar/*
==/UserStyle== */

/* Fondo general */
body, html {
    background-color: #e0e0e0 !important;
    color: #111 !important;
}

/* Estructura principal */
header, footer, main, section, article, aside {
    background-color: #d9d9d9 !important;
    color: #111 !important;
}

/* Cajas de texto, botones, formularios */
input, textarea, select, button {
    background-color: #d6d6d6 !important;
    color: #111 !important;
    border-color: #999 !important;
}

/* Enlaces */
a {
    color: #0044cc !important;
}

/* Evitar que el fondo tape imágenes o productos */
img, picture, video, svg, canvas, iframe {
    background-color: transparent !important;
}

/* No modificar el fondo de los contenedores de productos, banners o slides */
[class*="ui-item"], 
[class*="poly-card"], 
[class*="carousel"], 
[class*="slider"], 
[class*="banner"], 
[class*="gallery"], 
[class*="picture"], 
[class*="offer"], 
[class*="grid"], 
[class*="ui-search-result"], 
[class*="dynamic"] {
    background-color: transparent !important;
}

/* Tarjetas y paneles secundarios */
[class*="andes-card"], 
[class*="ui-panel"], 
[class*="box"], 
[class*="content"], 
[class*="wrapper"] {
    background-color: #d0d0d0 !important;
    color: #111 !important;
}
